def norm(s):
 mnx=min(r for r,c in s); mny=min(c for r,c in s); return frozenset((r-mnx,c-mny) for r,c in s)
def transforms(s):
 # dihedral on normalized shape
 out=[]
 for k in range(4):
  q=s
  for _ in range(k): q={(c,-r) for r,c in q}
  out.append(norm(q)); out.append(norm({(r,-c) for r,c in q}))
 return out
source={(0,0),(0,2),(1,1),(2,1)}
target={(0,0),(1,1),(1,2),(2,0)}
print([t==norm(target) for t in transforms(source)])

