def all_trans(s): return transforms(s)
def bestfit(shape, pts, H,W):
 results=[]
 for orient in all_trans(shape):
  h=max(r for r,c in orient)+1; w=max(c for r,c in orient)+1
  for r0 in range(H-h+1):
   for c0 in range(W-w+1):
    placed={(r0+r,c0+c) for r,c in orient}
    hits=len(placed&pts)
    results.append((hits,placed,orient,(r0,c0)))
 return sorted(results,key=lambda x:x[0],reverse=True)
