def rotcw(s):
 return norm({(c,-r) for r,c in s})
def fit_specific(shape, pts,H,W):
 sh=norm(shape); h=max(r for r,c in sh)+1; w=max(c for r,c in sh)+1
 rr=[]
 for i in range(H-h+1):
  for j in range(W-w+1):
   q={(i+r,j+c) for r,c in sh}; rr.append((len(q&pts),i,j,q,q&pts))
 return sorted(rr,reverse=True,key=lambda x:x[0])
