# function cw for arbitrary shapes correctly
# in standard matrix coords with normalized h,w

def rotate_cw_rect(s):
 s=norm(s); h=max(r for r,c in s)+1
 return norm({(c,h-1-r) for r,c in s})

def rank_placements(shape, pts, H=8,W=10):
 sh=rotate_cw_rect(shape);h=max(r for r,c in sh)+1;w=max(c for r,c in sh)+1
 out=[]
 for i in range(H-h+1):
  for j in range(W-w+1):
   q={(i+r,j+c) for r,c in sh};out.append((len(q&pts),i,j,q,q&pts))
 return sorted(out,reverse=True,key=lambda x:x[0])
for name,sh,pts in [('P1',T1,P1test),('P2',T2,P2test),('P3',T3,P3test)]:
 print(name,'rot',rotate_cw_rect(sh))
 print('residual rank excluding its own motif',rank_placements(sh,pts-sh)[:4])
 print('all union residual excluding motif',rank_placements(sh,U-sh)[:4])
